import{_ as e,o as r,c as s,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS Hammer (Day 1) - Clustered SCSI Target Using RBD","description":"","frontmatter":{"title":"CDS Hammer (Day 1) - Clustered SCSI Target Using RBD","date":"2014-10-29T00:00:00.000Z","updated":"2014-10-29T00:00:00.000Z","tags":["Ceph","RBD","Clustered Target","Distributed Storage","SCSI"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_1_-_Clustered_SCSI_Target_Using_RBD.md","filePath":"posts/2014/CDS_Hammer_Day_1_-_Clustered_SCSI_Target_Using_RBD.md","lastUpdated":1780459816000}'),l={name:"posts/2014/CDS_Hammer_Day_1_-_Clustered_SCSI_Target_Using_RBD.md"};function o(n,t,i,_,g,p){return r(),s("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 讨论Ceph分布式存储集群中RBD（RADOS Block Device）的集群化目标（Scuzzy Targets）实现方案</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Christy（提案人）、Mike、Jason、Josh等</p><p><strong>会议内容</strong>：</p><p><strong>1. 当前状态与问题</strong></p><ul><li>Linux HBA目标设备目前支持主动/被动模式，广泛支持Pacemaker，但仅支持无级别的故障转移。</li><li>这些实现主要依赖于虚拟端口，当主机故障时，被动端口的IP会接管。</li><li>单节点持久保留支持存在，但缺乏持久保留的主动/被动节点故障转移支持，导致数据损坏风险。</li></ul><p><strong>2. 集群化目标（Scuzzy Targets）方案</strong></p><ul><li>提出实现主动/主动HBA支持，简化启动支持和故障恢复，简化设置，支持多种传输协议。</li><li>主动/主动方案的缺点是实现更复杂，需要修改内核以进行分布式处理和命令执行设置。</li></ul><p><strong>3. 实现挑战</strong></p><ul><li><strong>请求执行和同步</strong>： 需要解决请求执行和同步问题，如比较和设置（Compare and Set）命令。</li><li><strong>持久保留支持</strong>： 需要支持持久保留，包括注册、查询、动态更改等。</li><li><strong>任务管理</strong>： 需要处理任务管理请求，如设备重置。</li></ul><p><strong>4. 实现方案</strong></p><ul><li><strong>请求执行和同步</strong>： 使用GLM（Global Lock Manager）或降低到底层设备进行锁定。</li><li><strong>持久保留支持</strong>： 将持久保留作为RBD图像属性持久化，或使用CephFS存储持久化信息。</li><li><strong>任务管理</strong>： 使用CephFS或用户空间代理处理任务管理请求。</li></ul><p><strong>5. 后续行动计划</strong></p><ul><li>完成RBD代码实现比较和设置命令。</li><li>研究持久保留支持的最佳方案。</li><li>实现任务管理功能。</li><li>设计和管理集群化目标的配置和管理接口。</li></ul><p><strong>会议结论</strong></p><p>本次会议讨论了Ceph集群中RBD的集群化目标实现方案，明确了实现挑战和解决方案，并制定了后续行动计划。实现集群化目标将提高RBD的可用性和可靠性，为Ceph集群提供更强大的功能。</p>',17)])])}const C=e(l,[["render",o]]);export{u as __pageData,C as default};
